# owner: platform
"""Seating charts: students sorted by last name, in rows."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: List[Student], seats: int) -> None:
    if seats <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")


def _sort_key(student: Student) -> tuple:
    return (
        student.last_name.lower(),
        student.first_name.lower()
    )


def _chunks(items: list, size: int) -> list:
    spans = range(0, len(items), size)
    return [items[i:i + size] for i in spans]


def _format_row(number: int, row: List[Student]) -> str:
    names = " | ".join(s.display_name for s in row)
    return f"Row {number}: {names}"


# ---
def seating_rows(
    students: List[Student], seats: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    _check(students, seats)
    ordered = sorted(students, key=_sort_key)
    rows = _chunks(ordered, seats)
    numbered = enumerate(rows, 1)
    return [_format_row(n, r) for n, r in numbered]

